import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BuUvxvtQ.js";const u=JSON.parse('{"title":"Dev Center","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/dev-center.md","filePath":"web-app/dev-center.md"}'),s={name:"web-app/dev-center.md"};function n(i,e,d,c,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="dev-center" tabindex="-1">Dev Center <a class="header-anchor" href="#dev-center" aria-label="Permalink to &quot;Dev Center&quot;">​</a></h1><p>The Dev Center is available only to authorised developer accounts. Open <strong>Dev Center</strong> from the app menu. Other accounts cannot access its workspaces or developer API actions.</p><h2 id="find-the-right-workspace" tabindex="-1">Find the right workspace <a class="header-anchor" href="#find-the-right-workspace" aria-label="Permalink to &quot;Find the right workspace&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Workspace</th></tr></thead><tbody><tr><td>Review a request to close an account</td><td>Deletion requests</td></tr><tr><td>Continue an account conversation</td><td>User messages</td></tr><tr><td>Reply to a bug report or suggestion</td><td>Feedback tickets</td></tr><tr><td>Draft, preview or publish a product update</td><td>Changelog</td></tr><tr><td>Check provider connectivity</td><td>Service health</td></tr><tr><td>Investigate failed API requests or response times</td><td>API activity</td></tr><tr><td>Find an account and review its access or usage</td><td>Users</td></tr><tr><td>Review restricted account access</td><td>Bans &amp; restrictions</td></tr></tbody></table><p>The sidebar highlights the current workspace. On a small screen, expand <strong>Navigate</strong> to switch tools. Every workspace has its own address, so bookmarks and the browser Back button work normally. <strong>Back to Sky Style</strong> returns to the product dashboard.</p><h2 id="support-and-accounts" tabindex="-1">Support and accounts <a class="header-anchor" href="#support-and-accounts" aria-label="Permalink to &quot;Support and accounts&quot;">​</a></h2><p>Deletion requests can be searched and filtered by status. Read the request, add an optional note, then approve or decline it. Approval records a decision; account deletion is a separate operation.</p><p>Open a conversation from a deletion request or use <strong>Users → Open conversation</strong> for another account. Feedback tickets are separate from these messages. Failed message requests retain the reply draft; refresh the conversation before retrying an uncertain send.</p><p>Account changes and exports are audited. Review the account identity and the operation&#39;s confirmation before changing access or deleting data.</p><h2 id="publishing-and-monitoring" tabindex="-1">Publishing and monitoring <a class="header-anchor" href="#publishing-and-monitoring" aria-label="Permalink to &quot;Publishing and monitoring&quot;">​</a></h2><p>Use the Changelog editor&#39;s preview to check the public result. A successful save is read back before the editor clears. If verification fails, the draft stays available; refresh before retrying to avoid an accidental duplicate.</p><p>Service health shows provider reachability, measurement times and cached results. Refresh does not bypass the probe cache or generate an AI outfit. Use <strong>API activity</strong> for individual request failures; an operational health response does not guarantee every request succeeds.</p>',12)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
